def get_parameters(
    vault: SmartContractVault, param_fetcher_id: str = POINTS_ACCRUAL_POF_ID
) -> dict[str, datetime | Decimal | str | None]:
    """Get points accrual parameters from vault fetcher.

    Args:
        vault (SmartContractVault): Vault object
        param_fetcher_id (str, optional): Points accrual parameter fetcher id. Defaults to
            POINTS_ACCRUAL_POF_ID.

    Returns:
        dict[str, datetime | Decimal | str | None]: Points accrual parameters
    """
    return vault.get_parameters_observation(fetcher_id=param_fetcher_id).parameters


def _append_to_state(
    state: state_utils.SmartContractState,
    balance_fetcher_id: str = common_fetchers.ALL_BALANCES_ET_BOF_ID,
    param_fetcher_id: str = POINTS_ACCRUAL_POF_ID,
) -> state_utils.SmartContractState:
    """Updates the contract state with balances and points accrual parameters."""
    return state_utils.append_to_state(
        state=state,
        parameters=get_parameters(state.vault, param_fetcher_id),
        balances=state.vault.get_balances_observation(fetcher_id=balance_fetcher_id).balances,
    )


def _get_balance_at_address(balances: Mapping, address: str, denomination: str) -> Decimal:
    """Gets the net balance at a specific address."""
    return balances[(address, DEFAULT_ASSET, denomination, Phase.COMMITTED)].net


def _get_points_rate_for_category(
    merchant_category: str,
    travel_portal_rate: Decimal,
    travel_dining_rate: Decimal,
    other_rate: Decimal,
) -> Decimal:
    """Determines the points multiplier based on merchant category.

    Args:
        merchant_category: The merchant category from instruction_details.
        travel_portal_rate: Points per £1 for travel portal bookings.
        travel_dining_rate: Points per £1 for travel and dining.
        other_rate: Points per £1 for all other purchases.

    Returns:
        The points rate multiplier.
    """
    if merchant_category == CATEGORY_TRAVEL_PORTAL:
        return travel_portal_rate
    elif merchant_category == CATEGORY_TRAVEL_DINING:
        return travel_dining_rate
    else:
        return other_rate


def accrue_points(
    state: state_utils.SmartContractState,
    transaction_amount: Decimal,
    merchant_category: str,
    transaction_type: str,
    account_type: str = "",
    fetchers_config: PointsAccrualFetchersConfig = DEFAULT_POINTS_ACCRUAL_FETCHERS_CONFIG,
) -> list[CustomInstruction]:
    """Accrues or claws back reward points for a transaction (post_posting_hook).

    Positive amounts accrue points. Negative amounts (refunds) claw back points,
    capped at the current REWARDS_POINTS balance to prevent negative points.

    Points are NOT earned/clawed back on cash advances or fee transactions.

    Args:
        state: The current state of the smart contract.
        transaction_amount: The transaction amount (positive for purchase, negative for refund).
        merchant_category: Category from instruction_details["merchant_category"].
        transaction_type: Type from instruction_details["transaction_type"].
        account_type: The account type for GL impact details.
        fetchers_config: Configuration for the fetchers.

    Returns:
        List of custom instructions for points accrual or clawback.
    """
    # Cash advances and fees do not earn/lose points
    if transaction_type in NON_EARNING_TRANSACTION_TYPES:
        return []

    if transaction_amount == 0:
        return []

    state = _append_to_state(
        state=state,
        param_fetcher_id=fetchers_config.param_fetcher_id,
    )

    rejection = state_utils.check_parameters_exist(
        state=state,
        param_ids={
            fetchers_config.denomination_param_id,
            POINTS_RATE_TRAVEL_PORTAL_PARAM.id,
            POINTS_RATE_TRAVEL_DINING_PARAM.id,
            POINTS_RATE_OTHER_PARAM.id,
        },
    )
    assert rejection is None, rejection

    denomination: str = str(state.parameters[fetchers_config.denomination_param_id])
    travel_portal_rate: Decimal = state.parameters[POINTS_RATE_TRAVEL_PORTAL_PARAM.id]  # type: ignore
    travel_dining_rate: Decimal = state.parameters[POINTS_RATE_TRAVEL_DINING_PARAM.id]  # type: ignore
    other_rate: Decimal = state.parameters[POINTS_RATE_OTHER_PARAM.id]  # type: ignore

    rate = _get_points_rate_for_category(
        merchant_category, travel_portal_rate, travel_dining_rate, other_rate
    )

    if transaction_amount > 0:
        # Points accrual: floor(amount * rate)
        points = (transaction_amount * rate).quantize(Decimal("1"), rounding=ROUND_DOWN)

        if points <= 0:
            return []

        return [
            CustomInstruction(
                postings=posting_utils.create_postings(
                    amount=points,
                    debit_account=state.vault.account_id,
                    debit_address=apex_addresses.REWARDS_POINTS,
                    credit_account=state.vault.account_id,
                    credit_address=DEFAULT_ADDRESS,
                    denomination=denomination,
                ),
                instruction_details=posting_utils.standard_instruction_details(
                    description=f"Points accrual: {points} ({rate}x on {merchant_category})",
                    event_type=POINTS_ACCRUAL_EVENT,
                    gl_impacted=False,
                    account_type=account_type,
                ),
                override_all_restrictions=True,
            )
        ]
    else:
        # Refund clawback: floor(abs(amount) * rate), capped at current balance
        clawback = (abs(transaction_amount) * rate).quantize(Decimal("1"), rounding=ROUND_DOWN)

        if clawback <= 0:
            return []

        current_points = _get_balance_at_address(
            state.balances, apex_addresses.REWARDS_POINTS, denomination
        )
        # Cap clawback at current points balance to prevent negative points
        clawback = min(clawback, max(current_points, Decimal(0)))

        if clawback <= 0:
            return []

        # Reverse the accrual: credit REWARDS_POINTS, debit DEFAULT
        return [
            CustomInstruction(
                postings=posting_utils.create_postings(
                    amount=clawback,
                    debit_account=state.vault.account_id,
                    debit_address=DEFAULT_ADDRESS,
                    credit_account=state.vault.account_id,
                    credit_address=apex_addresses.REWARDS_POINTS,
                    denomination=denomination,
                ),
                instruction_details=posting_utils.standard_instruction_details(
                    description=(
                        f"Points clawback: {clawback} ({rate}x on {merchant_category} refund)"
                    ),
                    event_type=POINTS_ACCRUAL_EVENT,
                    gl_impacted=False,
                    account_type=account_type,
                ),
                override_all_restrictions=True,
            )
        ]
